public class OrderFulfillmentOrchestrator
{
    public async Task ExecuteAsync(Order order)
    {
        await _stateMachine.TransitionAsync(order.Id, FulfillmentState.ReserveInventory);
        try
        {
            await _inventoryService.ReserveAsync(order);
            await _stateMachine.TransitionAsync(order.Id, FulfillmentState.ChargePayment);
            await _paymentService.ChargeAsync(order);
            await _stateMachine.TransitionAsync(order.Id, FulfillmentState.Ship);
            await _shippingService.LabelAsync(order);
            await _stateMachine.TransitionAsync(order.Id, FulfillmentState.Complete);
        }
        catch (InventoryUnavailableException)
        {
            await _paymentService.RefundAsync(order);
            await _stateMachine.TransitionAsync(order.Id, FulfillmentState.Failed);
        }
    }
}

// Use Temporal or a lightweight state machine
// Temporal gives you durable execution with retries and timeouts

[WorkflowActivity]
public Task ReserveInventoryAsync(Order order);
[WorkflowActivity]
public Task ChargePaymentAsync(Order order);
[WorkflowActivity]
public Task ShipOrderAsync(Order order);

public class OrderWorkflow : Workflow
{
    [WorkflowRun]
    public async Task RunAsync(Order order)
    {
        await ReserveInventoryAsync(order);
        await ChargePaymentAsync(order);
        await ShipOrderAsync(order);
    }
}
